patterns.approved_fix:
Classify message via classifyOperatorError before passing to RuntimeError:

export function createValidationError(message: string, context: RuntimeErrorContext, ...): RuntimeError {
  const classified = classifyOperatorError(new Error(message), { context: 'validation' });
  const safeMessage = classified.operatorMessage;
  return new RuntimeError(safeMessage, {...});
}

patterns.approved_fix_strategy:
Option A (Recommended): Update custom error class constructors to accept message and classify internally:

class NotFoundError extends Error {
  constructor(entityType: string, entityId: string) {
    const message = `${entityType} not found`;
    const classified = classifyOperatorError(new Error(message), { context: 'not_found' });
    super(classified.operatorMessage);
    this.name = 'NotFoundError';
  }
}

Option B: Classify at throw site:

const classified = classifyOperatorError(new Error(...), { context: '...' });
throw new NotFoundError(classified.operatorMessage);
